<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require MIZ_ROOT.'/app/pages.php';if(!installed())redirect('install.php');$error=null;$recovery=null;
if($_SERVER['REQUEST_METHOD']==='POST')try{verify_csrf($_POST['_csrf']??null);$email=strtolower(trim((string)($_POST['email']??'')));rate_limit('recovery-ip',client_ip(),12);rate_limit('recovery-email',$email,5);$p=validate_password($_POST['password']??null);if($p!==($_POST['password_repeat']??''))fail(422,'PASSWORD','تکرار رمز یکسان نیست.');$u=one('SELECT id,recovery_hash FROM '.table('users').' WHERE email=?',[$email]);$candidate=recovery_hash((string)($_POST['recovery']??''));if(!$u||!hash_equals($u['recovery_hash'],$candidate))fail(422,'RECOVERY','ایمیل یا کد بازیابی درست نیست.');[$recovery,$hash]=new_recovery();$q=query('UPDATE '.table('users').' SET password_hash=?,recovery_hash=?,session_version=session_version+1 WHERE id=? AND recovery_hash=?',[password_digest($p),$hash,$u['id'],$candidate]);if(!$q->rowCount())fail(409,'RECOVERY','کد قبلاً استفاده شده است.');query('DELETE FROM '.table('room_presence').' WHERE user_id=?',[$u['id']]);logout_user();}catch(ApiError $e){$error=$e->getMessage();$recovery=null;}catch(Throwable $e){error_log('Miz recovery failure '.$e->getCode());$error='بازیابی انجام نشد؛ دوباره امتحان کن.';$recovery=null;}
page_start($recovery?'رمز تازه‌ات آماده است.':'بازیابی دسترسی','با ایمیل و کد اختصاصی');if($recovery){message('رمز تغییر کرد؛ نشست‌های قبلی پایان یافتند.',true);echo '<p>کد قبلی دیگر معتبر نیست. این کد جدید را ذخیره کن.</p><code class="recovery-code">'.e($recovery).'</code><a class="primary-button" href="'.e(url('login.php')).'">ورود با رمز تازه</a>';page_end();exit;}message($error);?><form method="post"><?php csrf_field();field('ایمیل','email','email',$_POST['email']??'','email');field('کد بازیابی','recovery','text','','off');field('رمز تازه','password','password','','new-password');field('تکرار رمز تازه','password_repeat','password','','new-password');?><button class="primary-button" type="submit">ساخت رمز تازه</button></form><div class="account-links"><a href="<?=e(url('login.php'))?>">برگشت به ورود</a></div><?php page_end(); ?>
